// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about World Quiz: the data (countries.js, generated by
// tools/build_map.py) and every text the engine shows. Static text (title,
// help, button labels before the script runs) is in index.html. Contract:
// shared/map-quiz/README.md.
//
// Four rounds, cycling: the countries, then their capitals, both without
// the 36 small states (small: true in countries.js; drawn as context land
// there, never hit); then all 197 by name and by capital, the small ones
// with rings. Brunei, Kosovo, Luxembourg, Montenegro and Qatar have rings
// in every round (their largest drawn shape is under 4 map units across).
import { MAP, COUNTRIES } from './countries.js';

const misclicks = (n) => (n ? ` · ${n} misclick${n === 1 ? '' : 's'}` : ' · no misclicks');
// A territory carries the state it belongs to: "Greenland (Denmark)".
const named = (c) => (c.of ? `${c.name} (${c.of})` : c.name);
const capitalOf = (c) => `${named(c)} · ${c.capital}`;
// Every entry is one map piece; a round's answers are the entries it plays.
const answer = (c) => ({ ...c, pieces: [c.id] });
const MAIN = COUNTRIES.filter((c) => !c.small).map(answer);
const ALL = COUNTRIES.map(answer);
const smalls = ALL.length - MAIN.length;

export default {
  map: MAP,
  items: COUNTRIES.map((c) => ({ id: c.id })),
  rounds: [
    {
      key: 'countries',
      label: 'Countries',
      prompt: 'Find',
      answers: MAIN,
      ask: named,
      miss: named,
      done: ({ total, misses }) => `All ${total} countries found${misclicks(misses)}. Now their capitals.`,
    },
    {
      key: 'capitals',
      label: 'Capitals',
      prompt: 'Find the country or territory whose capital is',
      answers: MAIN,
      ask: (c) => c.capital,
      miss: capitalOf,
      done: ({ total, misses }) => `All ${total} capitals found${misclicks(misses)}. Next: all countries, with the ${smalls} small states.`,
    },
    {
      key: 'all-countries',
      label: 'All countries',
      prompt: 'Find',
      answers: ALL,
      ask: named,
      miss: named,
      done: ({ total, misses }) => `All ${total} countries found${misclicks(misses)}. Now all their capitals.`,
    },
    {
      key: 'all-capitals',
      label: 'All capitals',
      prompt: 'Find the country or territory whose capital is',
      answers: ALL,
      ask: (c) => c.capital,
      miss: capitalOf,
      done: ({ total, misses }) => `All ${total} capitals found${misclicks(misses)}. The countries again, without the small states.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Click the country with this name. Zoom: mouse wheel or pinch. Move: drag or two-finger scroll.',
      touch: 'Tap the country with this name. Pinch to zoom, drag to move.',
    },
    newGame: 'New game: counters at zero, countries first.',
    reset: 'Reset the quiz',
    resetArmed: 'Really reset? Counters and colours are cleared',
    mapError: 'The map could not be loaded. Reload the page to try again.',
    theme: (other, override) => ({
      label: `Switch to ${other} theme`,
      title: override ? `Back to the system setting (${other})` : `Switch to the ${other} theme`,
    }),
    roundPicker: 'Pick a round (starts it fresh)',
  },
  // A fresh round shows only what it asks: rounds 1 and 2 leave the small
  // states out (inert), rounds 3 and 4 add them, so carried colours would
  // mix found and not yet found.
  carryColours: false,
  // The round label is a picker: go straight to "All countries" (with the
  // small states) or any other round, which starts fresh.
  roundPicker: true,
  // maxScale 60: at the closest zoom 1 map unit (about 40 km) is 60 px, so
  // Malta, Andorra, Grenada and most other small states become shapes to
  // tap; the smallest (Vatican City, Monaco, Nauru, Tuvalu, San Marino)
  // keep their rings. besideHud: the net reaches the window's top-right
  // corner (Antarctica's piece). panToCentre: any part of the net can be
  // dragged to the middle, also at the full view, e.g. Australia before a
  // pinch about the screen's centre (owner, after testing on a phone).
  view: { maxScale: 60, besideHud: true, panToCentre: true },
};
